#[test]
fn zero_arg_cstring_getters() {
    for name in STR_FNS {
        let (c, r) = sym::<unsafe extern "C" fn() -> *const c_char>(name);
        unsafe {
            let cp = c();
            let rp = r();
            assert!(!cp.is_null(), "{name}(): C returned NULL");
            assert!(!rp.is_null(), "{name}(): Rust returned NULL");
            assert_eq!(
                CStr::from_ptr(cp),
                CStr::from_ptr(rp),
                "{name}(): string mismatch"
            );
        }
    }
}

/// `sodium_runtime_has_*` must agree: this build defines no HAVE_* macros, but
/// the C code still probes CPUID at runtime, so the Rust translation has to
/// reproduce whatever the C detects on THIS machine.
#[test]
fn runtime_feature_detection() {
    for name in [
        "sodium_runtime_has_neon",
        "sodium_runtime_has_armcrypto",
        "sodium_runtime_has_sse2",
        "sodium_runtime_has_sse3",
        "sodium_runtime_has_ssse3",
        "sodium_runtime_has_sse41",
        "sodium_runtime_has_avx",
        "sodium_runtime_has_avx2",
        "sodium_runtime_has_avx512f",
        "sodium_runtime_has_pclmul",
        "sodium_runtime_has_aesni",
        "sodium_runtime_has_rdrand",
    ] {
        if !has(name) {
            continue;
        }
        let (c, r) = sym::<unsafe extern "C" fn() -> i32>(name);
        let (cv, rv) = unsafe { (c(), r()) };
        assert_eq!(cv, rv, "{name}(): C={cv} Rust={rv}");
    }
}

/// The two exported `struct randombytes_implementation` globals must have
/// identical layout-visible content (the function pointers differ, but the
/// implementation_name they return must match).
#[test]
fn randombytes_implementation_globals() {
    #[repr(C)]
    struct Impl {
        implementation_name: Option<unsafe extern "C" fn() -> *const c_char>,
        random: Option<unsafe extern "C" fn() -> u32>,
        stir: Option<unsafe extern "C" fn()>,
        uniform: Option<unsafe extern "C" fn(u32) -> u32>,
        buf: Option<unsafe extern "C" fn(*mut std::ffi::c_void, usize)>,
        close: Option<unsafe extern "C" fn() -> i32>,
    }
    for g in [
        "randombytes_internal_implementation",
        "randombytes_sysrandom_implementation",
    ] {
        let (c, r) = sym::<*const Impl>(g);
        unsafe {
            assert!(!c.is_null() && !r.is_null(), "{g}: null global");
            let cn = (*c).implementation_name.expect("C name fn");
            let rn = (*r).implementation_name.expect("Rust name fn");
            assert_eq!(
                CStr::from_ptr(cn()),
                CStr::from_ptr(rn()),
                "{g}.implementation_name"
            );
            // Every slot must be non-NULL in both, or NULL in both.
            assert_eq!((*c).random.is_some(), (*r).random.is_some(), "{g}.random");
            assert_eq!((*c).stir.is_some(), (*r).stir.is_some(), "{g}.stir");
            assert_eq!((*c).uniform.is_some(), (*r).uniform.is_some(), "{g}.uniform");
            assert_eq!((*c).buf.is_some(), (*r).buf.is_some(), "{g}.buf");
            assert_eq!((*c).close.is_some(), (*r).close.is_some(), "{g}.close");
        }
    }
}

/// sodium_library_version_* and the version string.
#[test]
fn version_surface() {
    let (c, r) = sym::<unsafe extern "C" fn() -> i32>("sodium_library_version_major");
    unsafe { assert_eq!(c(), r()) };
    let (c, r) = sym::<unsafe extern "C" fn() -> i32>("sodium_library_version_minor");
    unsafe { assert_eq!(c(), r()) };
    let (c, r) = sym::<unsafe extern "C" fn() -> i32>("sodium_library_minimal");
    unsafe { assert_eq!(c(), r()) };
}

